/**
 * SignUpSource - Version 1.0.0
 * A simple tool to collect where users come from.
 * 
 * This file simulates the CDN version of the script
 * that would be included in websites.
 */
(function() {
    // Create SignUpSource modal when loaded
    function createSignUpSourceModal(options) {
        // Default options
        options = options || {};
        const id = options.id || '';
        const title = options.title || 'Where did you hear about us?';
        const description = options.description || 'Please let us know how you found our website.';
        const buttonText = options.buttonText || 'Submit';
        const callback = options.callback;
        const checkItems = options.checkItems || [
            { id: 'search', label: 'Google Search' },
            { id: 'social', label: 'Social Media' },
            { id: 'friend', label: 'Friend Recommendation' },
            { id: 'ad', label: 'Advertisement' },
            { id: 'other', label: 'Other' }
        ];

        // Create modal container
        const modal = document.createElement('div');
        modal.id = 'signupsource-modal';
        modal.style.cssText = 'display:none; position:fixed; z-index:9999; left:0; top:0; width:100%; height:100%; background-color:rgba(0,0,0,0.5); overflow:auto;';
        
        // Create modal content
        const modalContent = document.createElement('div');
        modalContent.style.cssText = 'background-color:#fff; margin:15% auto; padding:20px; border-radius:8px; width:90%; max-width:500px; box-shadow:0 4px 8px rgba(0,0,0,0.2);';
        
        // Add title
        const titleEl = document.createElement('h2');
        titleEl.textContent = title;
        titleEl.style.cssText = 'margin-bottom:15px; color:#333;';
        
        // Add description
        const descEl = document.createElement('p');
        descEl.textContent = description;
        descEl.style.cssText = 'margin-bottom:20px; color:#555;';
        
        // Add check items
        const itemsContainer = document.createElement('div');
        itemsContainer.style.cssText = 'margin-bottom:20px;';
        
        checkItems.forEach(item => {
            const itemDiv = document.createElement('div');
            itemDiv.style.cssText = 'margin-bottom:8px; display:flex; align-items:center;';
            
            const checkbox = document.createElement('input');
            checkbox.type = 'checkbox';
            checkbox.id = item.id;
            checkbox.style.cssText = 'margin-right:8px;';
            
            const label = document.createElement('label');
            label.textContent = item.label;
            label.htmlFor = item.id;
            
            itemDiv.appendChild(checkbox);
            itemDiv.appendChild(label);
            itemsContainer.appendChild(itemDiv);
        });
        
        // Add button
        const btn = document.createElement('button');
        btn.textContent = buttonText;
        btn.style.cssText = 'background-color:#4a69bd; color:white; border:none; padding:10px 20px; width:100%; border-radius:4px; cursor:pointer;';
        
        // Add event listener to button
        btn.addEventListener('click', function() {
            const userCheckedItems = [];
            
            // Collect checked items
            checkItems.forEach(item => {
                const checkbox = document.getElementById(item.id);
                if (checkbox && checkbox.checked) {
                    userCheckedItems.push({
                        id: item.id,
                        label: item.label
                    });
                }
            });
            
            // Call callback if provided
            if (callback && typeof callback === 'function') {
                callback(userCheckedItems);
            } else {
                // Default callback - send to server
                console.log('SignUpSource: Sending data to server');
                console.log('Website ID:', id);
                console.log('User checked items:', userCheckedItems);
                
                // Simulate sending data to server
                setTimeout(function() {
                    console.log('SignUpSource: Data sent successfully');
                }, 500);
            }
            
            // Hide modal
            modal.style.display = 'none';
        });
        
        // Add close functionality
        modal.addEventListener('click', function(e) {
            if (e.target === modal) {
                modal.style.display = 'none';
            }
        });
        
        // Assemble modal
        modalContent.appendChild(titleEl);
        modalContent.appendChild(descEl);
        modalContent.appendChild(itemsContainer);
        modalContent.appendChild(btn);
        modal.appendChild(modalContent);
        
        // Add modal to body
        document.body.appendChild(modal);
        
        // Show modal
        modal.style.display = 'block';
    }
    
    // Expose global function
    window.signupsource = createSignUpSourceModal;
})(); 